CHANGES:

Change #1: [Category: Model Architecture]
- What: Add LightGBM (native categorical), XGBoost (ordinal), and HistGradientBoosting, alongside the existing DCN-V2, all trained per fold; weight their probabilities via grid search on OOF.
- Why: With 8k rows and ~21 heavily categorical features, GBDTs dominate tabular performance; the current pure neural slice leaves a large gap. LightGBM's native categorical splits and XGB's tree regularization capture ordinal/interaction structure (income tier, distance, venue affinity) that the DCN learns slowly at this data scale.

Change #2: [Category: Feature Engineering]
- What: Add occupation frequency encoding to the FeatureBuilder (fit on training rows), and add an `is_never_venue` / `is_ever_venue` bucket indicator derived from venue affinity.
- Why: Occupation has 25 levels; frequency encoding compresses rare levels into a smooth numeric signal for trees. Bucketing venue affinity gives GBDTs direct split points for the strongest single driver of acceptance.

WHY current solution limited:
- Root cause: single small neural model on limited data; high variance, no GBDT prior.
- Evidence: 3-fold DCN with threshold tuning lands at 0.7123; training loss drops fast while val_acc plateaus — classic underfit-regularize tradeoff of a NN on small tabular data, where GBDTs typically score 0.73–0.75.

HOW these changes address it:
- Mechanism: GBDTs excel on small tabular data with monotone/ordinal features; soft-voting with the NN diversifies error modes. Frequency encoding removes ordinal gaps; venue-affinity buckets expose the strongest signal directly to trees.
- Expected improvement: 0.712 → ~0.740–0.750.
- Synergy: GBDT captures FE-derived ordinality; NN captures embedding interactions; ensemble weights tuned on OOF ensure each family contributes only where it helps.

KEEP UNCHANGED:
- Random seed: 42
- Data split: StratifiedKFold(n_splits=3, shuffle=True, random_state=42) on training rows only
- Persist full pipeline under --model; predict loads read-only
- Threshold tuned on OOF ensemble probs
- Output columns row_id,prediction

---

```python
"""
solution.py
Hybrid GBDT + DCN-V2 ensemble for coupon acceptance.

train  -> fits 3-fold LightGBM / XGBoost / HistGB / DCN-V2, saves models +
          feature builder + category maps + ensemble weights + threshold.
predict-> loads artifacts read-only, averages within/between families,
          applies threshold, writes row_id,prediction.
"""

from __future__ import annotations

import os
import re
import json
import pickle
import argparse
import time as _time
from typing import Dict, List, Optional, Tuple

import numpy as np
import pandas as pd

torch = None
try:
    import torch as _torch
    import torch.nn as _nn
    torch = _torch
    nn = _nn
    _HAS_TORCH = True
except Exception:
    _HAS_TORCH = False

from sklearn.model_selection import StratifiedKFold
from sklearn.ensemble import HistGradientBoostingClassifier

try:
    import lightgbm as lgb
    _HAS_LGB = True
except Exception:
    _HAS_LGB = False

try:
    import xgboost as xgb
    _HAS_XGB = True
except Exception:
    _HAS_XGB = False

if _HAS_TORCH:
    torch.set_num_threads(2)


# ============================================================================
# Feature engineering (stateful, fit on training rows only)
# ============================================================================
FREQUENCY_MAP = {"never": 0, "less1": 1, "1~3": 2, "4~8": 3, "gt8": 4}

VENUE_COLS = [
    "Bar", "CoffeeHouse", "CarryAway", "RestaurantLessThan20", "Restaurant20To50",
]
CAT_RAW = ["coupon", "time", "expiration", "gender", "maritalStatus", "occupation"]

EDUCATION_MAP = {
    "some high school": 0,
    "high school graduate": 1,
    "some college - no degree": 2,
    "associates degree": 3,
    "bachelors degree": 4,
    "graduate degree (masters, doctorate)": 5,
}


def _parse_age(v):
    if pd.isna(v):
        return np.nan
    s = str(v).strip().lower()
    if "below" in s:
        return 20.0
    if "plus" in s:
        return 50.0
    m = re.search(r"(\d+)", s)
    return float(m.group(1)) if m else np.nan


def _parse_income(v):
    if pd.isna(v):
        return np.nan
    s = str(v).replace(",", "")
    m = re.search(r"(\d+)", s)
    return float(m.group(1)) if m else np.nan


def _parse_time(v):
    if pd.isna(v):
        return np.nan
    s = str(v).upper().replace(" ", "")
    m = re.match(r"(\d+)(AM|PM)", s)
    if not m:
        return np.nan
    h = int(m.group(1))
    ap = m.group(2)
    if ap == "PM" and h != 12:
        h += 12
    if ap == "AM" and h == 12:
        h = 0
    return float(h)


def _parse_expiration(v):
    if pd.isna(v):
        return np.nan
    s = str(v).strip().lower()
    if "h" in s:
        return 2.0
    if "d" in s:
        return 24.0
    return np.nan


def _parse_freq(v):
    if pd.isna(v):
        return np.nan
    return FREQUENCY_MAP.get(str(v).strip().lower(), np.nan)


def _parse_education(v):
    if pd.isna(v):
        return np.nan
    return EDUCATION_MAP.get(str(v).strip().lower(), np.nan)


def _coupon_venue(coupon):
    if pd.isna(coupon):
        return None
    s = str(coupon).lower()
    if "bar" in s:
        return "Bar"
    if "coffee" in s:
        return "CoffeeHouse"
    if "carry" in s or "take" in s:
        return "CarryAway"
    if "20" in s and "50" in s:
        return "Restaurant20To50"
    if "20" in s:
        return "RestaurantLessThan20"
    return None


class FeatureBuilder:
    def __init__(self):
        self.fill_values_: Dict[str, object] = {}
        self.num_medians_: Dict[str, float] = {}
        self.const_cols_: List[str] = []
        self.cat_cols_: List[str] = []
        self.num_cols_: List[str] = []
        self.feature_cols_: List[str] = []
        self.occ_freq_: Dict[str, float] = {}
        self.fitted_ = False

    def _engineer(self, df):
        df = df.copy()
        out = pd.DataFrame(index=df.index)

        present_venues = [c for c in VENUE_COLS if c in df.columns]
        if present_venues:
            out["n_missing_venues"] = df[present_venues].isna().sum(axis=1).astype(float)

        for c, v in self.fill_values_.items():
            if c in df.columns:
                df[c] = df[c].fillna(v)

        if "temperature" in df.columns:
            out["temperature"] = pd.to_numeric(df["temperature"], errors="coerce")
        if "age" in df.columns:
            out["age"] = df["age"].map(_parse_age)
        if "income" in df.columns:
            out["income"] = df["income"].map(_parse_income)
        if "education" in df.columns:
            out["education_ord"] = df["education"].map(_parse_education)
        if "has_children" in df.columns:
            out["has_children"] = pd.to_numeric(df["has_children"], errors="coerce")
        if "expiration" in df.columns:
            out["expiration_hours"] = df["expiration"].map(_parse_expiration)
        if "time" in df.columns:
            out["time_hour"] = df["time"].map(_parse_time)

        for c in VENUE_COLS:
            if c in df.columns:
                out[c] = df[c].map(_parse_freq)

        freq_present = [c for c in VENUE_COLS if c in out.columns]
        if freq_present:
            out["total_venue_freq"] = out[freq_present].sum(axis=1, min_count=1)

        if "coupon" in df.columns and freq_present:
            venue_freq = pd.Series(np.nan, index=df.index, dtype=float)
            venue_name = df["coupon"].map(_coupon_venue)
            for col in present_venues:
                mask = venue_name == col
                if mask.any():
                    venue_freq.loc[mask] = out.loc[mask, col]
            out["venue_affinity"] = venue_freq
            out["is_venue_frequent"] = (venue_freq >= 2).astype(float)
            out["is_ever_venue"] = (venue_freq >= 1).astype(float)
            out["is_never_venue"] = (venue_freq == 0).astype(float)

        geq15 = pd.to_numeric(df["toCoupon_GEQ15min"], errors="coerce") if "toCoupon_GEQ15min" in df.columns else None
        geq25 = pd.to_numeric(df["toCoupon_GEQ25min"], errors="coerce") if "toCoupon_GEQ25min" in df.columns else None
        if geq15 is not None:
            out["toCoupon_GEQ15min"] = geq15
        if geq25 is not None:
            out["toCoupon_GEQ25min"] = geq25
        if geq15 is not None and geq25 is not None:
            tier = np.where(geq15 == 0, 0.0, np.where(geq25 == 0, 1.0, 2.0))
            out["distance_tier"] = tier
        if "direction_same" in df.columns:
            out["direction_same"] = pd.to_numeric(df["direction_same"], errors="coerce")

        if "occupation" in df.columns and self.occ_freq_:
            out["occ_freq"] = df["occupation"].astype(str).map(self.occ_freq_).fillna(0.0)

        for c in CAT_RAW:
            if c in df.columns:
                out[c] = df[c].astype(object).where(df[c].notna(), "missing")

        if "coupon" in df.columns and "time" in df.columns:
            out["coupon_time"] = df["coupon"].astype(str) + "|" + df["time"].astype(str)
        if "coupon" in df.columns and "expiration" in df.columns:
            out["coupon_exp"] = df["coupon"].astype(str) + "|" + df["expiration"].astype(str)

        return out

    def fit(self, df):
        df = df.copy()

        mode_cols = [c for c in (CAT_RAW + VENUE_COLS) if c in df.columns]
        for c in mode_cols:
            vc = df[c].dropna()
            self.fill_values_[c] = vc.mode().iloc[0] if len(vc) else "missing"

        if "occupation" in df.columns:
            vc = df["occupation"].astype(str).value_counts(normalize=True)
            self.occ_freq_ = vc.to_dict()

        eng = self._engineer(df)

        cat_keys = CAT_RAW + ["coupon_time", "coupon_exp"]
        num_candidates = [c for c in eng.columns if c not in cat_keys]
        for c in num_candidates:
            self.num_medians_[c] = float(eng[c].median()) if eng[c].notna().any() else 0.0
            eng[c] = eng[c].fillna(self.num_medians_[c])
        self.const_cols_ = [c for c in num_candidates if eng[c].nunique(dropna=True) <= 1]

        self.num_cols_ = [c for c in num_candidates if c not in self.const_cols_]
        self.cat_cols_ = [c for c in eng.columns if c in cat_keys]
        self.feature_cols_ = self.cat_cols_ + self.num_cols_
        self.fitted_ = True
        return self

    def transform(self, df):
        if not self.fitted_:
            raise RuntimeError("FeatureBuilder not fitted.")
        eng = self._engineer(df)
        for c in self.num_cols_:
            if c not in eng.columns:
                eng[c] = np.nan
            eng[c] = pd.to_numeric(eng[c], errors="coerce").fillna(self.num_medians_.get(c, 0.0))
        for c in self.cat_cols_:
            if c not in eng.columns:
                eng[c] = "missing"
            eng[c] = eng[c].astype(object).where(pd.notna(eng[c]), "missing")
        return eng[self.feature_cols_].copy()


def make_cv_splits(y, n_splits=3, seed=42):
    y = np.asarray(y)
    skf = StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=seed)
    return list(skf.split(np.zeros(len(y)), y))


# ============================================================================
# DCN-V2 model (unchanged)
# ============================================================================
if _HAS_TORCH:
    class TensorEncoder:
        def __init__(self, cat_cols=None):
            self.cat_cols_ = list(cat_cols) if cat_cols else []
            self.num_cols_ = []
            self.maps_ = {}
            self.cardinalities = []
            self.num_dim = 0
            self._mean = None
            self._std = None
            self.fitted_ = False

        def fit(self, X, cat_cols=None, num_cols=None):
            if cat_cols is not None:
                self.cat_cols_ = list(cat_cols)
            if num_cols is not None:
                self.num_cols_ = list(num_cols)
            else:
                self.num_cols_ = [c for c in X.columns if c not in self.cat_cols_]

            self.maps_, self.cardinalities = {}, []
            for c in self.cat_cols_:
                vals = X[c].astype(object).where(pd.notna(X[c]), "missing").astype(str)
                uniq = sorted(vals.unique().tolist())
                self.maps_[c] = {v: i + 1 for i, v in enumerate(uniq)}
                self.cardinalities.append(len(uniq) + 1)

            if self.num_cols_:
                num = X[self.num_cols_].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float64)
                num = np.nan_to_num(num, nan=0.0)
                self._mean = num.mean(axis=0)
                std = num.std(axis=0); std[std < 1e-8] = 1.0
                self._std = std
            else:
                self._mean = np.zeros(0); self._std = np.ones(0)
            self.num_dim = len(self.num_cols_)
            self.fitted_ = True
            return self

        def transform(self, X):
            n = len(X)
            cat = np.zeros((n, len(self.cat_cols_)), dtype=np.int64)
            for j, c in enumerate(self.cat_cols_):
                m = self.maps_[c]
                if c in X.columns:
                    vals = X[c].astype(object).where(pd.notna(X[c]), "missing").astype(str)
                    cat[:, j] = vals.map(lambda v: m.get(v, 0)).to_numpy(dtype=np.int64)
            if self.num_dim:
                num = X.reindex(columns=self.num_cols_).apply(pd.to_numeric, errors="coerce").to_numpy(dtype=np.float64)
                num = np.nan_to_num(num, nan=0.0)
                num = (num - self._mean) / self._std
                num = np.clip(num, -8.0, 8.0).astype(np.float32)
            else:
                num = np.zeros((n, 0), dtype=np.float32)
            return cat, num

    class FeatureGate(nn.Module):
        def __init__(self, dim, hidden=None, dropout=0.0):
            super().__init__()
            hidden = hidden or max(dim // 2, 8)
            self.net = nn.Sequential(
                nn.Linear(dim, hidden), nn.GELU(), nn.Dropout(dropout),
                nn.Linear(hidden, dim), nn.Sigmoid(),
            )
        def forward(self, x):
            return x * self.net(x) * 2.0

    class CrossLayerV2(nn.Module):
        def __init__(self, dim):
            super().__init__()
            self.linear = nn.Linear(dim, dim)
            nn.init.xavier_uniform_(self.linear.weight); nn.init.zeros_(self.linear.bias)
        def forward(self, x0, x):
            return x0 * self.linear(x) + x

    class DeepBranch(nn.Module):
        def __init__(self, in_dim, hidden=(128, 64), dropout=0.2):
            super().__init__()
            layers = []
            prev = in_dim
            for h in hidden:
                layers += [nn.Linear(prev, h), nn.BatchNorm1d(h), nn.GELU(), nn.Dropout(dropout)]
                prev = h
            layers.append(nn.Linear(prev, hidden[-1] if hidden else in_dim))
            self.net = nn.Sequential(*layers)
            self.out_dim = prev if not hidden else hidden[-1]
        def forward(self, x):
            return self.net(x)

    from dataclasses import dataclass, field
    @dataclass
    class DCNConfig:
        emb_dim: int = 8
        d_model: int = 48
        n_cross: int = 2
        deep_hidden: Tuple[int, ...] = (96, 48)
        dropout: float = 0.20
        gate_dropout: float = 0.10
        label_smoothing: float = 0.01
        lr: float = 2e-3
        weight_decay: float = 1e-4
        min_lr_ratio: float = 0.05

    class DCNv2Gated(nn.Module):
        def __init__(self, cardinalities, num_dim, cfg=None):
            super().__init__()
            cfg = cfg or DCNConfig()
            self.cfg = cfg
            self.num_dim = num_dim
            self.num_cat = len(cardinalities)
            self.embeddings = nn.ModuleList([nn.Embedding(card, cfg.emb_dim) for card in cardinalities])
            for emb in self.embeddings:
                nn.init.normal_(emb.weight, mean=0.0, std=0.05)
            cat_dim = self.num_cat * cfg.emb_dim
            self.cat_proj = nn.Linear(cat_dim, cfg.d_model) if cat_dim else None
            self.num_proj = nn.Linear(num_dim, cfg.d_model) if num_dim else None
            self.gate = FeatureGate(cfg.d_model, dropout=cfg.gate_dropout)
            self.cross_layers = nn.ModuleList([CrossLayerV2(cfg.d_model) for _ in range(cfg.n_cross)])
            self.deep = DeepBranch(cfg.d_model, cfg.deep_hidden, cfg.dropout)
            self.head = nn.Linear(cfg.d_model + self.deep.out_dim, 1)
            self._init_weights()

        def _init_weights(self):
            for m in self.modules():
                if isinstance(m, nn.Linear):
                    nn.init.xavier_uniform_(m.weight)
                    if m.bias is not None:
                        nn.init.zeros_(m.bias)
            nn.init.zeros_(self.head.weight); nn.init.zeros_(self.head.bias)

        def forward(self, cat, num):
            parts = []
            if self.cat_proj is not None:
                embs = [emb(cat[:, i]) for i, emb in enumerate(self.embeddings)]
                parts.append(self.cat_proj(torch.cat(embs, dim=-1)))
            if self.num_proj is not None:
                parts.append(self.num_proj(num))
            if not parts:
                raise RuntimeError("No inputs")
            x0 = parts[0] if len(parts) == 1 else parts[0] + parts[1]
            x0 = self.gate(x0)
            x = x0
            for layer in self.cross_layers:
                x = layer(x0, x)
            deep = self.deep(x0)
            return self.head(torch.cat([x, deep], dim=-1)).squeeze(-1)

    def _build_optimizer(model, cfg):
        decay, no_decay = [], []
        for name, p in model.named_parameters():
            if not p.requires_grad:
                continue
            if p.ndim < 2 or "embedding" in name or "norm" in name.lower():
                no_decay.append(p)
            else:
                decay.append(p)
        return torch.optim.AdamW(
            [{"params": decay, "weight_decay": cfg.weight_decay},
             {"params": no_decay, "weight_decay": 0.0}],
            lr=cfg.lr, betas=(0.9, 0.98), eps=1e-8,
        )


# ============================================================================
# Fold trainers per model family
# ============================================================================
def _run_lgb(X_aug, y_idx, splits, cat_cols, cat_categories, deadline, seed=42):
    if not _HAS_LGB:
        return None, []
    oof = np.zeros(len(y_idx)); mask = np.zeros(len(y_idx), dtype=bool); fold_models = []
    X_lgb = X_aug.copy()
    for c in cat_cols:
        X_lgb[c] = pd.Categorical(X_lgb[c].astype(str), categories=cat_categories[c])
    for fold, (tr, va) in enumerate(splits):
        if _time.time() > deadline:
            print(f"LGB skipping fold {fold + 1} (deadline)."); break
        m = lgb.LGBMClassifier(
            n_estimators=800, learning_rate=0.05, num_leaves=31,
            min_child_samples=20, feature_fraction=0.8,
            bagging_fraction=0.8, bagging_freq=5, lambda_l2=1.0,
            random_state=seed + fold, n_jobs=2, verbose=-1,
        )
        m.fit(X_lgb.iloc[tr], y_idx[tr], eval_set=[(X_lgb.iloc[va], y_idx[va])],
              callbacks=[lgb.early_stopping(50, verbose=False)])
        oof[va] = m.predict_proba(X_lgb.iloc[va])[:, 1]
        mask[va] = True
        fold_models.append(m)
    return {"probs": oof, "mask": mask}, fold_models


def _ordinal_frame(X_aug, cat_cols, cat_maps):
    Xo = X_aug.copy()
    for c in cat_cols:
        mp = cat_maps[c]
        Xo[c] = Xo[c].astype(str).map(lambda v: mp.get(v, 0)).astype(np.float32)
    return Xo


def _run_xgb(X_aug, y_idx, splits, cat_cols, cat_maps, deadline, seed=42):
    if not _HAS_XGB:
        return None, []
    oof = np.zeros(len(y_idx)); mask = np.zeros(len(y_idx), dtype=bool); fold_models = []
    Xo = _ordinal_frame(X_aug, cat_cols, cat_maps)
    for fold, (tr, va) in enumerate(splits):
        if _time.time() > deadline:
            print(f"XGB skipping fold {fold + 1} (deadline)."); break
        try:
            m = xgb.XGBClassifier(
                n_estimators=800, learning_rate=0.05, max_depth=5,
                min_child_weight=3, subsample=0.8, colsample_bytree=0.8,
                reg_lambda=1.0, random_state=seed + fold, n_jobs=2,
                eval_metric="logloss", early_stopping_rounds=50,
                use_label_encoder=False, verbosity=0,
            )
            m.fit(Xo.iloc[tr], y_idx[tr], eval_set=[(Xo.iloc[va], y_idx[va])], verbose=False)
        except TypeError:
            m = xgb.XGBClassifier(
                n_estimators=500, learning_rate=0.05, max_depth=5,
                min_child_weight=3, subsample=0.8, colsample_bytree=0.8,
                reg_lambda=1.0, random_state=seed + fold, n_jobs=2,
                verbosity=0,
            )
            m.fit(Xo.iloc[tr], y_idx[tr], verbose=False)
        oof[va] = m.predict_proba(Xo.iloc[va])[:, 1]
        mask[va] = True
        fold_models.append(m)
    return {"probs": oof, "mask": mask}, fold_models


def _run_hist(X_aug, y_idx, splits, cat_cols, cat_maps, deadline, seed=42):
    oof = np.zeros(len(y_idx)); mask = np.zeros(len(y_idx), dtype=bool); fold_models = []
    Xo = _ordinal_frame(X_aug, cat_cols, cat_maps)
    for fold, (tr, va) in enumerate(splits):
        if _time.time() > deadline:
            print(f"HIST skipping fold {fold + 1} (deadline)."); break
        m = HistGradientBoostingClassifier(
            max_iter=400, learning_rate=0.06, max_leaf_nodes=31,
            min_samples_leaf=20, l2_regularization=1.0,
            early_stopping=True, n_iter_no_change=30,
            validation_fraction=0.1, random_state=seed + fold,
        )
        m.fit(Xo.iloc[tr], y_idx[tr])
        oof[va] = m.predict_proba(Xo.iloc[va])[:, 1]
        mask[va] = True
        fold_models.append(m)
    return {"probs": oof, "mask": mask}, fold_models


def _train_one_fold_nn(X_tr_df, y_tr, X_va_df, y_va, cat_cols, num_cols,
                        fold, epochs, patience, seed, deadline):
    torch.manual_seed(seed + fold); np.random.seed(seed + fold)
    enc = TensorEncoder().fit(X_tr_df, cat_cols=cat_cols, num_cols=num_cols)
    cat_tr, num_tr = enc.transform(X_tr_df)
    cat_va, num_va = enc.transform(X_va_df)

    cat_tr_t = torch.from_numpy(cat_tr); num_tr_t = torch.from_numpy(num_tr)
    y_tr_t = torch.from_numpy(np.asarray(y_tr, dtype=np.float32))
    cat_va_t = torch.from_numpy(cat_va); num_va_t = torch.from_numpy(num_va)
    y_va_t = torch.from_numpy(np.asarray(y_va, dtype=np.float32))

    cfg = DCNConfig()
    model = DCNv2Gated(enc.cardinalities, enc.num_dim, cfg)
    criterion = nn.BCEWithLogitsLoss()
    opt = _build_optimizer(model, cfg)
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs, eta_min=cfg.lr * cfg.min_lr_ratio)

    best_val_loss = float("inf"); best_state = None; best_epoch = -1
    n = len(cat_tr_t); bs = 256

    for epoch in range(epochs):
        if _time.time() > deadline:
            print(f"NN fold {fold + 1} stopped at epoch {epoch + 1}."); break
        model.train()
